getSpace(): { spaceId: string; dimensions: number; rebuilding: boolean } | null {
  const row = this.db.prepare("SELECT value FROM embedding_meta WHERE key='vc_space'").get() as {value: string} | undefined;
  return row ? JSON.parse(row.value) : null;
}
configureSpace(spaceId: string, dimensions: number): any {
  const saved = this.getSpace();
  if (saved?.spaceId === spaceId && saved.dimensions !== dimensions) throw new Error("SPACE_CONFIG_CONFLICT");
  this.db.enableLoadExtension(true);
  require("sqlite-vec").load(this.db);
  this.db.enableLoadExtension(false);
  if (saved?.spaceId === spaceId && saved.dimensions === dimensions) {
    if (this.dimensions !== dimensions || !this.vecTablesReady) {
      this.dimensions = dimensions;
      this.initSchema();
    }
    return saved;
  }
  if (!spaceId || !Number.isInteger(dimensions) || dimensions < 1 || dimensions > 65536) throw new Error("SPACE_INVALID");
  this.dimensions = dimensions;
  this.dropVectorTables();
  this.initSchema();
  const state = { spaceId, dimensions, rebuilding: this.tableRowCount("l1_records") > 0 };
  this.db.prepare("INSERT OR REPLACE INTO embedding_meta VALUES('vc_space',?)").run(JSON.stringify(state));
  return state;
}
writeRebuiltVector(id: string, embedding: Float32Array, spaceId: string): void {
  const space = this.getSpace();
  if (!space?.rebuilding || space.spaceId !== spaceId || !this.stmtGetMeta.get(id)) throw new Error("SPACE_REBUILD_CONFLICT");
  if (embedding.length !== this.dimensions || !embedding.every(Number.isFinite) || embedding.every(v => v === 0)) throw new Error("EMBEDDING_INVALID");
  this.stmtDeleteVec!.run(id);
  this.stmtInsertVec!.run(id, Buffer.from(embedding.buffer, embedding.byteOffset, embedding.byteLength), "");
}
finishSpaceRebuild(spaceId: string, failures: number): any {
  const state = this.getSpace();
  const count = (this.db.prepare("SELECT count(*) n FROM l1_vec").get() as {n: number}).n;
  if (!state || state.spaceId !== spaceId || failures !== 0 || count !== this.tableRowCount("l1_records")) throw new Error("SPACE_REBUILD_INCOMPLETE");
  state.rebuilding = false;
  this.db.prepare("UPDATE embedding_meta SET value=? WHERE key='vc_space'").run(JSON.stringify(state));
  return state;
}

